#!/usr/bin/env python3
"""Rebuild the pinned Unicode reading data with Python's standard library.

By default this downloads the exact archive recorded in data/sources.lock.json.
Use --source /path/to/Unihan.zip to rebuild from an already downloaded archive.
--check compares the regenerated bytes with the checked-in output without writing.
"""

from __future__ import annotations

import argparse
import hashlib
import io
import json
from pathlib import Path
import re
import unicodedata
from urllib.request import Request, urlopen
import zipfile


ROOT = Path(__file__).resolve().parents[1]
SOURCE_ID = "unicode-unihan-17.0.0"
PROPERTIES = ("kMandarin", "kTGHZ2013", "kHanyuPinlu")


def checked_bytes(payload: bytes, expected: str, label: str) -> bytes:
    actual = hashlib.sha256(payload).hexdigest()
    if actual != expected:
        raise ValueError(f"{label}: SHA-256 mismatch: expected {expected}, got {actual}")
    return payload


def fetch(artifact: dict, local: Path | None = None) -> bytes:
    if local is not None:
        payload = local.read_bytes()
    else:
        request = Request(artifact["url"], headers={"User-Agent": "xiaohe-learn-data-import/1"})
        with urlopen(request, timeout=90) as response:
            payload = response.read()
    return checked_bytes(payload, artifact["sha256"], artifact["url"])


def modern_readings(properties: dict[str, str]) -> tuple[list[str], dict[str, list[str]]]:
    """Preserve source order; kMandarin's first value is the zh-Hans preference."""
    readings: list[str] = []
    sources: dict[str, list[str]] = {}
    for field in ("kMandarin", "kTGHZ2013"):
        for value in properties.get(field, "").split():
            # kTGHZ2013 prefixes readings with one or more dictionary locations.
            if field == "kTGHZ2013":
                if not re.fullmatch(r"(?:\d{3}\.\d{3},)*\d{3}\.\d{3}:[^\s:]+", value):
                    raise ValueError(f"Unexpected kTGHZ2013 value: {value!r}")
                value = value.split(":", 1)[1]
            for reading in value.split(","):
                reading = unicodedata.normalize("NFC", reading)
                if not reading:
                    raise ValueError("Empty reading")
                if reading not in sources:
                    readings.append(reading)
                    sources[reading] = []
                if field not in sources[reading]:
                    sources[reading].append(field)
    return readings, sources


def frequency(value: str) -> int:
    total = 0
    for reading in value.split():
        match = re.fullmatch(r"[^()]+\(([0-9]+)\)", reading)
        if match is None:
            raise ValueError(f"Unexpected kHanyuPinlu value: {reading!r}")
        total += int(match[1])
    return total


def generate(text: str) -> dict:
    selected: dict[str, dict[str, str]] = {}
    counts = {field: 0 for field in PROPERTIES}
    for line in text.splitlines():
        if not line or line.startswith("#"):
            continue
        codepoint, field, value = line.split("\t")
        if field not in PROPERTIES:
            continue
        character = chr(int(codepoint.removeprefix("U+"), 16))
        properties = selected.setdefault(character, {})
        if field in properties:
            raise ValueError(f"Duplicate source property: {codepoint} {field}")
        properties[field] = value
        counts[field] += 1

    characters = {}
    frequency_count = 0
    for character in sorted(selected, key=ord):
        properties = selected[character]
        readings, reading_sources = modern_readings(properties)
        if not readings:
            # The frequency list must not silently introduce historical readings.
            continue
        entry = {"readings": readings, "readingSources": reading_sources}
        if "kHanyuPinlu" in properties:
            entry["frequency"] = frequency(properties["kHanyuPinlu"])
            frequency_count += 1
        characters[character] = entry

    if counts != {"kMandarin": 44348, "kTGHZ2013": 8105, "kHanyuPinlu": 3799}:
        raise ValueError(f"Unexpected property counts: {counts}")
    if len(characters) != 44348 or frequency_count != 3799:
        raise ValueError("Unexpected generated coverage")
    return {
        "metadata": {
            "sourceId": SOURCE_ID,
            "unicodeVersion": "17.0.0",
            "readingPolicy": "kMandarin source order, then kTGHZ2013; no kHanyuPinyin historical readings",
            "preferredReadingPolicy": "The first kMandarin value is the source's zh-Hans preference; no context disambiguation",
            "frequencyPolicy": "Sum all kHanyuPinlu pronunciation counts; not a modern Internet frequency ranking",
            "frequencyCorpus": "1986 Xiandai Hanyu Pinlu Cidian; 1,807,389 ideographs across four genres; simplified/traditional counts can be duplicated",
            "characterCount": len(characters),
            "frequencyCharacterCount": frequency_count,
            "sourcePropertyCounts": counts,
            "license": "Unicode-3.0",
        },
        "characters": characters,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, help="Use a local, checksum-verified Unihan.zip")
    parser.add_argument("--output", type=Path, default=ROOT / "src/data/generated/readings.json")
    parser.add_argument("--check", action="store_true", help="Verify checked-in output without writing")
    args = parser.parse_args()
    lock = json.loads((ROOT / "data/sources.lock.json").read_text(encoding="utf-8"))
    source = next(item for item in lock["sources"] if item["id"] == SOURCE_ID)
    archive = fetch(source["artifacts"]["archive"], args.source)
    member = source["artifacts"]["readings"]
    with zipfile.ZipFile(io.BytesIO(archive)) as zipped:
        payload = checked_bytes(zipped.read(member["archiveMember"]), member["sha256"], member["archiveMember"])
    result = generate(payload.decode("utf-8"))
    output = (json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
    expected = source.get("generated", {}).get("sha256")
    if expected:
        checked_bytes(output, expected, "generated readings.json")
    if args.check:
        if not args.output.is_file() or args.output.read_bytes() != output:
            raise ValueError(f"Generated data differs from {args.output}")
    else:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_bytes(output)
    print(f"{'Verified' if args.check else 'Wrote'} {len(result['characters'])} characters, "
          f"{result['metadata']['frequencyCharacterCount']} frequency counts: {args.output}")


if __name__ == "__main__":
    main()
